from typing import Dict, List, Optional

# Import the necessary modules
import collections

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self._capacity = capacity
        self._cache: Dict[str, Any] = {}
        self._used: Dict[str, bool] = collections.defaultdict(bool)
        self._evicted: List[str] = []

    def get(self, key: str, default: Optional[Any] = None) -> Optional[Any]:
        if key not in self._cache:
            return default
        if self._used[key]:
            # Key is already used, but not the most recently used
            return self._cache[key]

        # If key is in cache and is the most recently used, return it
        if self._cache[key] is not None:
            del self._cache[key]
            self._used[key] = True
            return self._cache[key]
        else:
            self._used[key] = True
            return default

    def put(self, key: str, value: Any) -> Optional[str]:
        if key in self._cache:
            # Key already exists
            if self._capacity == 0:
                raise ValueError("capacity must be at least 1")

            # Evict least recently used if cache is full
            if len(self._cache) >= self._capacity:
                self._evicted.append(self._cache.popitem(last=False))
                self._used.popitem(last=False)

            self._cache[key] = value
            self._used[key] = True
            return key
        else:
            # Key not in cache
            self._cache[key] = value
            self._used[key] = True
            return key

    def len(self) -> int:
        return len(self._cache)

    def keys(self) -> List[str]:
        return list(self._cache.keys())

    def resize(self, capacity: int) -> List[str]:
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        # Evict least recently used keys until capacity is reached
        evicted_keys = []
        while len(self._cache) < self._capacity:
            key = self._cache.popitem(last=False)
            evicted_keys.append(key)

        return evicted_keys
