# lru.py
from typing import Dict, List, Optional
from collections import defaultdict
import time

class LRUCache:
    def __init__(self, capacity: int, ttl: Optional[int] = None, clock: Optional[time.__call__) = None):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._cache: Dict[str, Any] = {}
        self._used: Dict[str, bool] = defaultdict(bool)
        self._clock: Optional[time.__call__) = clock
        self._time_stored: Dict[str, int] = defaultdict(int)
        self._stats: Dict[str, int] = defaultdict(int)

    def get(self, key: str, default: Optional[Any] = None) -> Optional[Any]:
        if key not in self._cache:
            return default
        if self._clock is not None and key in self._time_stored:
            time_stored = self._time_stored[key]
            if (self._clock() - time_stored) >= ttl:
                # Key has expired
                self._stats["expirations"] += 1
                del self._cache[key]
                self._used[key] = False
                del self._time_stored[key]
                return default
            else:
                # Key is not expired, still in cache
                if self._used[key]:
                    # Already used, but not the most recently used
                    return self._cache[key]
                else:
                    self._cache[key] = value
                    return self._cache[key]
        else:
            # Key is not in cache or has expired, default to None
            return default

    def put(self, key: str, value: Any) -> Optional[str]:
        if key in self._cache:
            if self._clock is not None and key in self._time_stored:
                time_stored = self._time_stored[key]
                expiration_time = self._clock() - time_stored
                if expiration_time >= ttl:
                    # Key has expired
                    self._stats["expirations"] += 1
                    del self._cache[key]
                    del self._time_stored[key]
                    # If key is still in cache, it's still a hit but we don't count it
                    return key
            else:
                # Key is already in cache, but not the most recently used
                if self._used[key]:
                    return key
                else:
                    # Key was in cache and is not expired
                    self._time_stored[key] = self._clock()
                    self._cache[key] = value
                    return key
        else:
            if self._clock is not None and self._time_stored.get(key, 0) == 0:
                # Key is not in cache and has not expired
                self._time_stored[key] = self._clock()
                self._cache[key] = value
                return key
            else:
                # Key is not in cache and has expired
                self._stats["expirations"] += 1
                del self._cache[key]
                del self._time_stored[key]
                return key

    def len(self) -> int:
        return len(self._cache)

    def keys(self) -> List[str]:
        return list(self._cache.keys())

    def resize(self, capacity: int) -> List[str]:
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        # Evict least recently used keys until capacity is reached
        evicted_keys = []
        while len(self._cache) < self._capacity:
            key = self._cache.popitem(last=False)
            evicted_keys.append(key)

        return evicted_keys
