from fractions import Fraction
from typing import Optional

class CalcError(Exception):
    pass

def evaluate(expr: str) -> Fraction:
    """Evaluate an arithmetic expression exactly and report errors with their position."""

    # Check for empty string
    if not expr:
        return Fraction(0)

    # Check for invalid syntax
    start = 0
    current_token = []
    tokens = []

    while start < len(expr):
        # Skip spaces or tabs
        if expr[start].isspace():
            start += 1
            continue

        # Skip any non-alphanumeric characters
        if expr[start].isdigit():
            while start < len(expr) and expr[start].isdigit():
                start += 1
        elif expr[start] == '.':  # Handle decimal point
            if start + 1 < len(expr) and expr[start + 1].isdigit():
                # Skip the decimal part
                start += 1
            else:
                raise CalcError('Invalid decimal point')
        else:
            # Handle unary minus
            if expr[start] == '-':
                if start + 1 < len(expr) and expr[start + 1].isdigit():
                    # Skip the sign
                    start += 1
                else:
                    raise CalcError('Invalid unary minus')
            else:
                # Check if we are at a valid number
                if start >= len(expr):
                    break

                # Convert to Fraction
                num = Fraction()
                num.numerator = int(expr[start:start+1])
                num.denominator = 10
                start += 1

                # Handle decimal point
                if start < len(expr) and expr[start] == '.':  # Skip to next digit
                    start += 1
                else:
                    num.numerator = int(expr[start:start+1])
                    num.denominator = 10
                    start += 1

                # Handle other tokens
                if expr[start] == '+':
                    tokens.append(('add', num))
                    start += 1
                elif expr[start] == '-':
                    tokens.append(('subtract', num))
                    start += 1
                elif expr[start] == '*':
                    tokens.append(('multiply', num))
                    start += 1
                elif expr[start] == '/':
                    tokens.append(('divide', num))
                    start += 1
                elif expr[start] == '(':
                    tokens.append(('parentheses', start))
                    start += 1
                else:
                    # Handle other tokens
                    if expr[start].isdigit():
                        num = Fraction()
                        num.numerator = int(expr[start:start+1])
                        num.denominator = 10
                        start += 1
                    else:
                        # Handle unary minus
                        if expr[start] == '-':
                            if start + 1 < len(expr) and expr[start + 1].isdigit():
                                num = Fraction()
                                num.numerator = int(expr[start:start+1])
                                num.denominator = 10
                                num.numerator = -num.numerator
                                num.denominator = 10
                                start += 1
                        else:
                            raise CalcError('Invalid token')

    # Evaluate the tokens
    tokens = [token for token in tokens]
    result = Fraction()

    # Evaluate left-to-right, considering operator precedence
    for i, token in enumerate(tokens):
        if isinstance(token, str):
            continue
        elif token == 'parentheses':
            # Handle parentheses
            pass
        else:
            op, num = token
            if op == 'add':
                result = result + num
            elif op == 'subtract':
                result = result - num
            elif op == 'multiply':
                result = result * num
            elif op == 'divide':
                result = result / num
            else:
                raise CalcError('Invalid operator')

    # Check for syntax errors
    if not result.denominator:
        raise CalcError('Invalid syntax')

    # Report errors with their position
    error_pos = None
    for i, token in enumerate(tokens):
        if isinstance(token, str):
            continue
        elif token == 'parentheses':
            error_pos = i
        else:
            if isinstance(token, Fraction):
                if not result.denominator:
                    error_pos = i
            elif token == 'divide':
                if result.denominator == 0:
                    error_pos = i
                else:
                    error_pos = i

    return result
