import time
from typing import Optional, Callable, Any

class TokenBucket:
    def __init__(self, rate: float, capacity: float, clock: Callable[[], float]):
        if rate <= 0 or capacity <= 0:
            raise ValueError("rate and capacity must be positive")
        self.rate = rate
        self.capacity = capacity
        self._clock = clock
        self._current_time = 0.0  # Start at the time when the bucket is full
        self._tokens = capacity

    def _update_time(self):
        self._current_time = self._clock()

    def _refill(self):
        self._update_time()
        # Calculate tokens added since the last refill
        delta = (self._current_time - self._previous_time) * self.rate
        self._tokens += delta

    def _previous_time(self):
        return self._current_time

    def _check_refill(self):
        if self._tokens <= 0:
            self._refill()

    def _get_available(self):
        return self._tokens

    def _try_acquire(self, n: int) -> bool:
        if n <= 0:
            raise ValueError("n must be greater than 0")
        if n > self._tokens:
            return False
        self._tokens -= n
        return True

    def _wait_time(self, n: int) -> float:
        if n <= 0:
            raise ValueError("n must be greater than 0")
        # Calculate time until the next try
        if self._try_acquire(n):
            return 0.0
        else:
            return (self._current_time - self._previous_time) * self.rate

    def available(self) -> float:
        return self._tokens

    def refill(self):
        self._refill()
        self._update_time()  # To ensure the clock is updated

def main():
    pass

if __name__ == "__main__":
    main()
