import csv
from datetime import date
from decimal import Decimal

class LedgerError(Exception):
    pass

class OverdraftError(LedgerError):
    pass

class Transaction:
    def __init__(self, date, account, amount, line):
        self.date = date
        self.account = account.strip()
        self.amount = Decimal(amount)
        self.line = line

def parse(text: str) -> list[Transaction]:
    transactions = []
    lines = text.split('\n')

    # Skip empty lines
    for line in lines:
        if not line.strip():
            continue
        if not line.startswith('#'):
            try:
                date_str, account_str, amount_str = line.split(',')
                date = date(date_str)
                account = account_str.strip()
                amount = Decimal(amount_str)
                line_number = lines.index(line)
                transactions.append(Transaction(date, account, amount, line_number))
            except (ValueError, UnicodeDecodeError):
                raise LedgerError(f"Invalid line {line_number + 1}")
        # Skip lines that are not headers
    return transactions

def running_balances(transactions, opening=None, limits=None) -> list[tuple[Transaction, Decimal]]:
    if not transactions:
        return []

    balances = {}
    for account, limit in limits:
        balances[account] = Decimal('0') if account not in limits else limits[account]
    opening_balance = Decimal('0') if opening is None else opening

    for transaction in transactions:
        # Check if account is in limits
        account = transaction.account.strip()
        if account not in balances:
            balances[account] = Decimal('0')
        current_balance = balances[account]

        # Apply transaction
        new_balance = current_balance + Decimal(transaction.amount)

        # Check if overdraft limit applies
        if limits and account in limits:
            if new_balance < limits[account]:
                raise OverdraftError(transaction, account, new_balance)

        # Add to balances
        balances[account] = new_balance

    return [(transaction, new_balance) for transaction, new_balance in transactions]

def final_balances(transactions, opening=None, limits=None) -> dict[str, Decimal]:
    if not transactions:
        return {}

    balances = {}
    for account, limit in limits:
        balances[account] = Decimal('0') if account not in limits else limits[account]
    opening_balance = Decimal('0') if opening is None else opening

    for transaction in transactions:
        account = transaction.account.strip()
        if account not in balances:
            balances[account] = Decimal('0')
        new_balance = balances[account]
        new_balance = new_balance + Decimal(transaction.amount)

        # Check if overdraft applies
        if limits and account in limits:
            if new_balance < limits[account]:
                raise OverdraftError(transaction, account, new_balance)

        # Add to balances
        balances[account] = new_balance

    return balances
