import datetime
from datetime import timedelta
import re

def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    # Parse the cron expression
    cron_parts = re.split(r'(?<=\s|\*|[^<]*)', expr)
    if len(cron_parts) != 5:
        raise ValueError("Wrong number of fields")

    # Extract fields
    fields = cron_parts[0]

    # Split into individual fields (ignoring leading/trailing whitespace)
    fields = fields.strip()
    if not fields:
        raise ValueError("Empty item")

    # Split into individual field items
    items = fields.split(',')

    # Validate the cron expression
    if not all(item in '*/A-B*/S' for item in items):
        raise ValueError("Invalid item type")

    # Create a list of valid fields and their values
    valid_fields = []
    for i, item in enumerate(items):
        if item.startswith('*/'):
            # Handle day-of-month and minute fields
            if i == 0:
                # Day-of-month
                valid_fields.append(('day_of_month', item[2:]))
                if item[2] == '*':
                    valid_fields.append(('day_of_month', item[2]))
                else:
                    valid_fields.append(('day_of_month', item[2]))
            elif i == 1:
                # Hour
                valid_fields.append(('hour', item[2:]))
            elif i == 2:
                # Minute
                valid_fields.append(('minute', item[2:]))
            else:
                # Both day-of-month and minute fields
                valid_fields.append(('day_of_month', item[2:]))
                valid_fields.append(('minute', item[2:]))

    # If there are no valid fields, check if the after datetime is valid
    if not valid_fields:
        # Check day-of-week field
        if not valid_fields[0]:
            raise ValueError("Day of week field not restricted")
        # Check if month and day are valid
        month = valid_fields[0][0]
        day = valid_fields[0][1]
        # Check if day is valid for the month
        if month == 0:
            raise ValueError("Month 0 is invalid")
        if day < 1:
            raise ValueError("Day 0 is invalid")
        if month > 12:
            raise ValueError("Month must be 1–12")
        if day > 31:
            raise ValueError("Day of month must be 1–31")
        if month < 1:
            raise ValueError("Month must be 1–12")

    # Validate the cron expression
    # Create a list of valid values for each field
    valid_values = []
    for field, value in valid_fields:
        if field == 'day_of_month':
            # Handle * and N
            if value == '*':
                valid_values.append(('*', None))
            elif isinstance(value, str):
                if not value.isdigit():
                    raise ValueError("Invalid value")
                valid_values.append((value, int(value)))
            elif value.isdigit():
                valid_values.append((value, int(value)))
        elif field == 'hour':
            valid_values.append(('*', None))
        elif field == 'minute':
            valid_values.append(('*', None))
        else:
            # Both day-of-month and hour fields
            valid_values.append(('day_of_month', value))

    # Now, find the next time after after that matches all valid fields
    # We'll use the `datetime` module with microseconds set to 0
    # We'll use a timedelta to find the next occurrence

    # Calculate the earliest time after after
    result = after
    while True:
        result = result.replace(tzinfo=datetime.timezone.utc)
        if result + timedelta(seconds=1) > result:
            break

    # Check if result is valid
    if result is None:
        raise ValueError("No valid time found")

    # Check if result is after after
    if result < after:
        raise ValueError("Result is before the given time")

    # Check if all fields match
    match = True
    for field, value in valid_fields:
        if field == 'day_of_month':
            # Check that the day of the month matches
            if value is None:
                if not (1 <= int(value) <= 31):
                    match = False
                else:
                    pass
            else:
                if not (int(value) <= int(value) and int(value) >= 1):
                    match = False
        elif field == 'hour':
            if value is None:
                if not (0 <= int(value) <= 23):
                    match = False
                else:
                    pass
            else:
                if not (int(value) <= 23 and int(value) >= 0):
                    match = False
        elif field == 'minute':
            if value is None:
                if not (0 <= int(value) <= 59):
                    match = False
                else:
                    pass
            else:
                if not (int(value) <= 59 and int(value) >= 0):
                    match = False

    if not match:
        raise ValueError("No valid time found")

    return result
