from collections import Mapping

class PathError(Exception):
    pass

def parse(path: str) -> list[str | int]:
    if not path:
        return []

    segments = []
    current = []

    i = 0
    while i < len(path):
        if path[i] == '[':
            i += 1
            if i + 1 >= len(path):
                raise PathError(path)
            N = int(path[i + 1:i + 2])
            segments.append(N)
            i += 2
        elif path[i] == ']':
            i += 1
        elif path[i] == '"':
            i += 1
            if i + 1 >= len(path):
                raise PathError(path)
            current.append(path[i])
            i += 2
        else:
            if path[i] == '.':
                if i + 1 >= len(path):
                    raise PathError(path)
                segments.append(path[i])
                i += 1
            elif path[i] == '[':
                if i + 1 >= len(path):
                    raise PathError(path)
                segments.append('[')
                i += 1
                current.append('[')
            elif path[i] == ']':
                if i + 1 >= len(path):
                    raise PathError(path)
                segments.append(']')
                i += 1
            else:
                if i + 1 >= len(path):
                    raise PathError(path)
                segments.append(path[i])
                i += 1

    return segments + current

def get(obj, path: str, default=<none>) -> str:
    if not path:
        return str(obj)

    segments = parse(path)

    try:
        value = obj
        for segment in segments:
            if isinstance(segment, str):
                if not isinstance(obj, Mapping):
                    raise PathError(path)
                value = obj[segment]
            elif isinstance(segment, int):
                if not isinstance(obj, (list, tuple)):
                    raise PathError(path)
                value = obj[segments.index(segment)]
        return str(value)
    except KeyError as e:
        return str(default) if default is not None else str(obj)
    except IndexError as e:
        return str(default) if default is not None else str(obj)
    except PathError as e:
        raise PathError(path) from e
