# pq.py

import heapq

class TaskQueue:
    def __init__(self):
        self.heap = []
        self.locked_tasks = set()
        self.priorities = {}

    def push(self, task, priority):
        if task in self.priorities:
            raise ValueError("Task already queued")
        if task not in self.locked_tasks:
            self.locked_tasks.add(task)
        self.priorities[task] = priority
        heapq.heappush(self.heap, (priority, task))
        return

    def pop(self):
        if not self.heap:
            raise IndexError("Queue is empty")
        priority, task = heapq.heappop(self.heap)
        self.locked_tasks.discard(task)
        return (task, priority)

    def peek(self):
        if not self.heap:
            raise IndexError("Queue is empty")
        return self.heap[0]

    def reprioritize(self, task, new_priority):
        if task not in self.priorities:
            raise KeyError(f"Task {task} not queued")
        priority = self.priorities[task]
        self.priorities[task] = new_priority
        if priority == new_priority:
            return
        self.heap = []
        heapq.heappush(self.heap, (priority, task))
        return

    def remove(self, task):
        if task not in self.priorities:
            raise KeyError(f"Task {task} not queued")
        if task in self.locked_tasks:
            return
        if self.heap:
            heapq.heappop(self.heap)
            self.locked_tasks.remove(task)
            return
        else:
            raise KeyError(f"Task {task} not queued")

    def len(self):
        return len(self.heap)

    def task_in_queue(self, task):
        return task in self.locked_tasks

    def priority(self, task):
        return self.priorities[task]
