# A trie module for autocomplete functionality
# This module implements the Autocomplete class with case-insensitive matching and trie operations

import logging

class Autocomplete:
    def __init__(self):
        self.trie = {}
        self.word_count = 0
        self.word_list = []
        self.log = logging.getLogger(__name__)

    def add(self, word: str, weight: float = 1):
        if not word:
            raise ValueError("Word cannot be empty")

        # Normalize the word to case-insensitive form
        case_folded_word = word.casefold()

        # Check if a word with the same case-folded form already exists
        if case_folded_word in self.trie:
            # Update the stored word with the new weight and casefolded form
            self.trie[case_folded_word] = (self.trie[case_folded_word][0], weight)
            self.word_count += 1
            self.log.info(f"Updated word {word} (weight {weight}) in trie with form {case_folded_word}")
            return True

        # Add the new word with its weight
        self.trie[case_folded_word] = (word, weight)
        self.word_count += 1
        self.log.info(f"Added word {word} (weight {weight}) to trie with form {case_folded_word}")
        return True

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if not prefix:
            return sorted(self.trie.keys(), key=lambda x: (-self.trie[x][1], x))
        if k < 0:
            raise ValueError("k must be non-negative")

        # Normalize the prefix
        prefix_case_folded = prefix.casefold()

        # Retrieve words with casefolded prefix
        results = []
        for word, weight in self.trie.items():
            if word.startswith(prefix_case_folded):
                # Sort by weight descending and then by case-folded word
                results.append((weight, word))
                results.sort(reverse=True)  # Sort by weight descending

        # Return up to k words
        if k <= len(results):
            return results[:k]
        else:
            return results

    def delete(self, word: str) -> bool:
        if not word:
            return False

        case_folded_word = word.casefold()

        if case_folded_word not in self.trie:
            return False

        # Remove the stored word
        self.trie.pop(case_folded_word)
        self.word_count -= 1
        self.log.info(f"Deleted word {word} with form {case_folded_word}")
        return True

    def len(self):
        return self.word_count

    def word_in(self, word):
        return word in self.trie.values()
