import sys
import functools
from typing import List, Callable, Any

class EmitError(Exception):
    pass

class Emitter:
    def __init__(self):
        self._listeners = {}

    def on(self, event: str, listener: Callable) -> Callable:
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append((listener, event))
        return listener

    def once(self, event: str, listener: Callable) -> Callable:
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event] = [(listener, event, 0)]  # track removal
        return listener

    def off(self, event: str, listener=None) -> int:
        if listener is None:
            # Remove all registrations for this event
            for _, _, _ in self._listeners[event]:
                self._listeners[event].pop()
            return 0
        # Remove the first occurrence
        for index, (listener, event, _count) in enumerate(self._listeners[event]):
            if listener is listener:
                return _count
        return 0

    def emit(self, event: str, *args, **kwargs) -> int:
        # Call all registered listeners in registration order
        calls = 0
        for event_listener, event, count in self._listeners[event]:
            if event_listener is not None:
                calls += functools.reduce(lambda a, b: a + b, (event, args, kwargs), 0)
        return calls

    def listeners(self, event: str) -> List[Callable]:
        if event not in self._listeners:
            return []
        return [event_listener for _, event_listener, _count in self._listeners[event]]

# Example usage:
if __name__ == "__main__":
    e = Emitter()
    e.on("event1", lambda x: print(x))
    e.once("event1", lambda x: print(x))
    e.off("event1", lambda x: print(x))
    e.emit("event1", "hello")
    print(e.listeners("event1"))
