# money.py
from decimal import Decimal, getcontext
from decimal import ROUND_HALF_UP, ROUND_DOWN, ROUND_FLOOR

def to_cents(x):
    """Convert a number to cents, rounded to two decimal places with banker's rounding."""
    if isinstance(x, str):
        x = x.replace(',', '.').replace('-', '')
        x = x.replace('.', '')
        try:
            return Decimal(x).quantize(Decimal('0.00'), rounding=ROUND_HALF_UP)
        except ValueError:
            raise ValueError("Input is not a finite decimal")
    elif isinstance(x, int):
        return Decimal(str(x)).quantize(Decimal('0.00'), rounding=ROUND_HALF_UP)
    else:
        raise TypeError("Input is not a valid decimal")

def allocate(amount, ratios):
    """Split amount into parts according to the ratios using the largest-remainder rule."""
    if not ratios:
        raise ValueError("ratios cannot be empty")
    if not all(isinstance(r, int) for r in ratios) or all(isinstance(r, Decimal) for r in ratios):
        ratios = [int(r) if isinstance(r, int) else r for r in ratios]
        if sum(ratios) == 0:
            raise ValueError("sum of ratios must be positive")
    if amount < 0:
        amount = -amount

    cents = to_cents(amount)
    total_rations = sum(ratios)
    if total_rations == 0:
        raise ValueError("sum of ratios must be positive")

    parts = [0] * total_rations
    remainder = amount

    for r in ratios:
        share = (remainder * r) / total_rations
        rounded_down = round(share, 0)
        rounded = round(share, 2)
        parts[r - 1] = Decimal(str(rounded))
        remainder = remainder - rounded

        if remainder == 0:
            break

    return parts

def split_even(amount, n):
    """Split amount evenly across n parts."""
    if n < 1:
        raise ValueError("n must be at least 1")
    return allocate(amount, [1] * n)

def format_money(amount):
    """Format money with commas and two decimal places, with a minus for negative."""
    cents = to_cents(amount)
    if cents.is_zero():
        return '0.00'
    parts = [f"{part:.2f}" for part in cents.quantize(Decimal('0.00'), rounding=ROUND_HALF_UP)]
    sign = '-' if amount < 0 else ''
    return f"{sign},{','.join(parts)}"
