# paths.py
import heapq

def dijkstra(graph, src):
    """Returns shortest path distances and predecessors from 'src'."""
    if src not in graph:
        raise KeyError(f"Node '{src}' not found in graph")

    dist = {}
    prev = {}

    # Initialize distances
    dist[src] = 0
    prev[src] = None
    heap = [(0, src, [])]

    while heap:
        current_dist, current_node, path = heapq.heappop(heap)

        if current_node in dist and current_dist < dist[current_node]:
            continue

        if current_node not in dist or current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            if current_dist + weight < dist[neighbor]:
                dist[neighbor] = current_dist + weight
                prev[neighbor] = current_node
                heapq.heappush(heap, (dist[neighbor], neighbor, path + [neighbor]))

    return dist, prev

def shortest_path(graph, src, dst):
    """Returns the shortest path from 'src' to 'dst'."""
    if src not in graph or dst not in graph:
        raise KeyError(f"Node '{src}' not found or node '{dst}' not found in graph")

    if src == dst:
        return [src]

    dist, prev = dijkstra(graph, src)

    path = []
    current = dst
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()

    return path
