import re
import typing

def placeholders(template: str) -> list[str]:
    placeholders = []
    for i, char in enumerate(template):
        if char in '{':
            placeholders.append(template[i:i+1])  # Check for placeholder start
        if char == '{' and i + 1 < len(template) and template[i+1] == ':':  # Check for placeholder with default
            placeholders.append(template[i+1:i+1 + 2])  # Check for placeholder with default
    return placeholders

def render(template: str, values: typing.Mapping[str, typing.Any]) -> str:
    placeholders = placeholders(template)
    result = []
    for placeholder in placeholders:
        name, default = placeholder[0], placeholder[1:]
        if name in values:
            result.append(str(values[name]))
        else:
            if default is not None and default:
                result.append(default)
            else:
                result.append(name)  # If the default is missing, and there's no name, fallback
    return ''.join(result)

class TemplateError(ValueError):
    pass

class MissingKey(KeyError):
    pass

def check_template(template: str):
    placeholders = placeholders(template)
    if len(placeholders) == 0:
        raise TemplateError("Template is empty")
    for i, placeholder in enumerate(placeholders):
        if not placeholder:
            raise TemplateError(f"Missing placeholder at position {i}")
    return True

def check_render(template: str, values: typing.Mapping[str, typing.Any]) -> None:
    placeholders = placeholders(template)
    if len(placeholders) == 0:
        raise TemplateError("Template is empty")
    for i, placeholder in enumerate(placeholders):
        name, default = placeholder
        if name not in values:
            raise MissingKey(name)
    return True

def get_template_error(template: str, position: int):
    if template[position] == '{':
        return TemplateError(position, f"Invalid placeholder at position {position}")
    return None

def get_missing_key_error(name: str, values: typing.Mapping[str, typing.Any]) -> KeyError:
    if name not in values:
        raise KeyError(name)
    return None

def get_default(name: str, default: str) -> str:
    return default or name

def render_template(template: str, values: typing.Mapping[str, typing.Any]) -> str:
    placeholders = placeholders(template)
    result = []
    for i, placeholder in enumerate(placeholders):
        if not placeholder:
            raise TemplateError(f"Missing placeholder at position {i}")
        name, default = placeholder[0], placeholder[1:]
        if name in values:
            result.append(str(values[name]))
        else:
            if default is not None and default:
                result.append(default)
            else:
                result.append(name)  # If the default is missing and there's no name, fallback
    return ''.join(result)

def check_template_errors(template: str):
    placeholders = placeholders(template)
    if not placeholders:
        raise TemplateError("Template is empty")
    for i, placeholder in enumerate(placeholders):
        if not placeholder:
            raise TemplateError(f"Missing placeholder at position {i}")
    return True

def get_template_error_position(template: str, position: int) -> int:
    if template[position] == '{':
        return position
    return -1
