from dataclasses import FrozenClass, dataclass

from datetime import date
from decimal import Decimal, ROUND_HALF_UP

from typing import List, Optional, Dict, Tuple, Optional, Union, Final, Optional

class InventoryError(Exception):
    pass

class UnknownItemError(InventoryError):
    pass

class InsufficientStockError(InventoryError):
    pass

class Item(FrozenClass):
    def __init__(self, sku: str, name: str, category: str):
        self.sku = sku
        self.name = name
        self.category = category

class Movement(FrozenClass):
    def __init__(self, seq: int, day: date, kind: str, sku: str, qty: int, location: str, to_location: Optional[str] = None, unit_cost: Decimal | None = None):
        self.seq = seq
        self.day = day
        self.kind = kind
        self.sku = sku
        self.qty = qty
        self.location = location
        self.to_location = to_location
        self.unit_cost = unit_cost

class Ledger:
    def __init__(self):
        self.items = []
        self.movements = []

    def add_item(self, item: Item) -> None:
        if item.sku in self.items:
            raise ValueError("SKU already exists")

        # Add the item to the ledger
        self.items.append(item)
        # Store the item in the ledger for future reference
        self.items.append(item)
        self.movements.append(Movement(seq=len(self.items) - 1, day=date(2023, 1, 1), kind="receive", sku=item.sku, qty=item.qty, location=item.location, unit_cost=Decimal(item.unit_cost)))

    def item(self, sku: str) -> Item:
        if not self.is_known_sku(sku):
            raise UnknownItemError
        return self.items[self.items.index(sku)]

    def items(self) -> List[Item]:
        return self.items

    def movements(self, sku: Optional[str] = None, as_of: Optional[date] = None) -> List[Movement]:
        if sku:
            return [movement for movement in self.movements if movement.sku == sku]
        return [movement for movement in self.movements]

    def on_hand(self, sku: Optional[str], location: Optional[str], as_of: Optional[date] = None) -> int:
        if not self.is_known_sku(sku):
            raise UnknownItemError
        total = 0
        for movement in self.movements(as_of=as_of):
            if movement.sku == sku:
                total += movement.qty
        return total

    def locations(self) -> List[str]:
        return [item.location for item in self.items]

class Valuation(FrozenClass):
    def __init__(self, qty: int, value: Decimal, cogs: Decimal):
        self.qty = qty
        self.value = value
        self.cogs = cogs

    def __eq__(self, other):
        return self.qty == other.qty and self.value == other.value and self.cogs == other.cogs

    def __repr__(self):
        return f"Valuation(qty={self.qty}, value={self.value}, cogs={self.cogs})"

class ValuationError(Exception):
    pass

class FIFO(Valuation):
    def __init__(self, ledger, sku, as_of=None):
        self.ledger = ledger
        self.sku = sku
        self.as_of = as_of or date(2023, 1, 1)

    def fifo(self, ledger, sku, as_of=None):
        # Each receipt adds a cost layer
        # An issue consumes the oldest layers first, possibly across several layers
        # value is the sum of quantity × unit cost over what is left of the layers
        # cogs is the sum of quantity × unit cost over everything issued
        value = Decimal(0)
        cogs = Decimal(0)
        layers = []

        # Process each movement
        for movement in self.ledger.movements:
            if movement.sku == sku:
                # Add the current layer to the layers list
                layers.append(movement.qty * movement.unit_cost)
                # Add the layer to the value and cogs
                value += movement.qty * movement.unit_cost
                cogs += movement.qty * movement.unit_cost

        # Calculate the final value and cogs
        return Valuation(qty=self.ledger.on_hand(sku, as_of=self.as_of), value=value, cogs=cogs)

    def average(self, ledger, sku, as_of=None):
        running_quantity = 0
        running_value = 0
        cogs = Decimal(0)

        # Process each movement
        for movement in self.ledger.movements:
            if movement.sku == sku:
                if movement.kind == "receive":
                    running_quantity += movement.qty
                    running_value += movement.qty * movement.unit_cost
                    cogs += running_value
                else:
                    # Issue consumes the oldest layers first
                    issued_quantity = running_quantity
                    issued_value = running_value
                    # Subtract the issued quantity from the running quantity
                    running_quantity -= issued_quantity
                    # Subtract the issued value from the running value
                    running_value -= issued_value
                    cogs -= issued_value

        # Calculate the final value and cogs
        return Valuation(qty=self.ledger.on_hand(sku, as_of=self.as_of), value=Decimal(running_value), cogs=cogs)

    def evaluate(self, ledger, sku, method="fifo", as_of=None):
        if method not in ["fifo", "average"]:
            raise ValuationError(f"Unknown method: {method}")

        if not self.is_known_sku(sku):
            raise ValuationError("Unknown SKU")

        # Process each movement
        valuations = []
        cogs = Decimal(0)
        layers = []

        # Process each movement
        for movement in self.ledger.movements:
            if movement.sku == sku:
                if movement.kind == "receive":
                    # Add the current layer to the layers list
                    layers.append(movement.qty * movement.unit_cost)
                    # Add the layer to the value and cogs
                    valuations.append(Valuation(qty=movement.qty, value=Decimal(movement.qty * movement.unit_cost), cogs=Decimal(movement.qty * movement.unit_cost)))
                else:
                    # Issue consumes the oldest layers first
                    issued_quantity = movement.qty
                    issued_value = movement.qty * movement.unit_cost
                    # Subtract the issued quantity from the running quantity
                    running_quantity -= issued_quantity
                    # Subtract the issued value from the running value
                    running_value -= issued_value
                    cogs -= issued_value
                    valuations.append(Valuation(qty=running_quantity, value=running_value, cogs=cogs))

        # Calculate the final value and cogs
        valuations = sorted(valuations, key=lambda x: x.qty)
        return Valuation(qty=valuations[0].qty, value=valuations[0].value, cogs=valuations[0].cogs)

    def __repr__(self):
        return f"Valuation(qty={self.qty}, value={self.value}, cogs={self.cogs})"

class StockReport(Exception):
    pass

class ValuationReport(Exception):
    pass

def stock_report(ledger: Ledger, as_of: Optional[date] = None, location: Optional[str] = None) -> str:
    # Stock on hand grouped by location
    result = []
    if location:
        location_group = ledger.locations()[location]
        # Add the group to the result
        result.append(f"{location},sku,qty")
        for sku, qty in location_group.items():
            result.append(f"{location},{sku},{qty}")
        # Add the total for this location
        result.append(f"{location},{sku},{qty}")
    else:
        # Add all locations
        for location in ledger.locations():
            location_group = ledger.locations()[location]
            # Add the group to the result
            result.append(f"{location},sku,qty")
            for sku, qty in location_group.items():
                result.append(f"{location},{sku},{qty}")
            # Add the total for this location
            result.append(f"{location},{sku},{qty}")
    # Add the grand total
    result.append(f"TOTAL,,{total}")
    return "\n".join(result)

def valuation_report(ledger: Ledger, as_of: Optional[date] = None, method: str = "fifo", category: Optional[str] = None) -> str:
    # Stock on hand across all locations and its value
    result = []
    if method == "fifo":
        valuations = ledger.fifo(sku=category, as_of=as_of)
    elif method == "average":
        valuations = ledger.average(sku=category, as_of=as_of)
    elif method == "evaluate":
        valuations = ledger.evaluate(sku=category, method=method, as_of=as_of)
    else:
        raise ValuationError(f"Invalid method: {method}")

    # Group by category
    group_by_category = {}
    for sku, val in valuations.items():
        if category and category != val.sku:
            group_by_category[val.category] = group_by_category.get(val.category, []) + [val]
    # Sort and format the result
    group_by_category = sorted(group_by_category.items(), key=lambda x: x[0])
    result.append(f"{category},{sku},{qty},{value}")
    for sku, val in group_by_category:
        result.append(f"{category},{sku},{qty},{value}")
    # Add the total for the category
    result.append(f"{category},{sku},{qty},{value}")
    # Add the grand total
    result.append(f"TOTAL,,{total}")
    return "\n".join(result)

