        start = datetime.today()
    balance = Decimal(0.0)
    for entry in account.entries:
        if entry.day <= start:
            balance += get_balance(entry.account, start)
    return balance

def get_entries(account: Account, start: Optional[datetime.date] = None) -> List[Entry]:
    entries = []
    for entry in account.entries:
        if entry.day <= start:
            entries.append(entry)
    return entries

def get_account_lines(account: Account, start: Optional[datetime.date] = None) -> List[Entry]:
    entries = get_entries(account, start)
    return entries

def get_entries_from_account(account: Account, start: Optional[datetime.date] = None) -> List[Entry]:
    if start is None:
        start = datetime.today()
    entries = []
    for entry in get_entries(account, start):
        entries.append(entry)
    return entries

def get_balance_from_entries(entries: List[Entry], start: Optional[datetime.date] = None) -> Decimal:
    if start is None:
        start = datetime.today()
    total = Decimal(0.0)
    for entry in entries:
        if entry.day <= start:
            total += get_balance(entry.account, start)
    return total

def get_ledger_rows(account: Account, start: Optional[datetime.date] = None, end: Optional[datetime.date] = None) -> List[LedgerRow]:
    if start is None and end is None:
        start = datetime.today()
    ledger_rows = []
    for entry in get_entries(account, start):
        ledger_rows.append(LedgerRow(number=entry.number, day=start, memo=entry.memo, debit=Decimal(entry.debit), credit=Decimal(entry.credit), balance=Decimal(entry.debit - entry.credit)))
    return ledger_rows

# Functions for Journal
class UnbalancedEntryError(ValueError):
    pass

class Line:
    def __init__(self, account: str, debit: Decimal, credit: Decimal):
        self.account = account
        self.debit = debit
        self.credit = credit

class Entry:
    def __init__(self, number: int, day: datetime.date, memo: str, lines: Tuple[Line, ...]):
        self.number = number
        self.day = day
        self.memo = memo
        self.lines = lines

class LedgerRow:
    def __init__(self, number: int, day: datetime.date, memo: str, debit: Decimal, credit: Decimal, balance: Decimal):
        self.number = number
        self.day = day
        self.memo = memo
        self.debit = debit
        self.credit = credit
        self.balance = balance

class Journal:
    def __init__(self, chart: Chart):
        self.chart = chart
        self.entries = []

    def post(self, day: datetime.date, memo: str, lines: Tuple[Line, ...]) -> Entry:
        # Check if entries exist and are valid
        if len(lines) < 2:
            raise UnbalancedEntryError(VALUE_ERROR)
        for line in lines:
            if not line.account:
                raise KeyError("account is None")
            if not is_valid_debit(line.debit):
                raise ValueError("debit amount should be positive")
            if not is_valid_credit(line.credit):
                raise ValueError("credit amount should be positive")
            if not line.account in self.chart.accounts:
                raise KeyError("account does not exist")
            if not is_leaf(line.account):
                raise ValueError("account must be a leaf")

        # Check if entries are valid
        for line in lines:
            if not line.debit:
                raise ValueError("debit amount must be zero")
            if not line.credit:
                raise ValueError("credit amount must be zero")

        # Check if debits and credits balance
        if Decimal(line.debit - line.credit) != Decimal(0):
            raise UnbalancedEntryError("UnbalancedEntryError")

        # Add entries to the journal
        for line in lines:
            entry = Entry(number=len(self.entries) + 1, day=day, memo=memo, lines=lines)
            self.entries.append(entry)

        # Create LedgerRows
        ledger_rows = []
        for entry in self.entries:
            ledger_rows.append(LedgerRow(number=entry.number, day=entry.day, memo=entry.memo, debit=Decimal(entry.debit), credit=Decimal(entry.credit), balance=Decimal(entry.debit - entry.credit)))

        return Entry(number=len(self.entries), day=day, memo=memo, lines=lines)

    def entries(self) -> List[Entry]:
        return self.entries

    def balance(self, code: str, start: Optional[datetime.date] = None, end: Optional[datetime.date] = None) -> Decimal:
        if start is None:
            start = datetime.today()
        elif end is None:
            end = datetime.today()

        if code not in self.chart.accounts:
            raise KeyError(f"account does not exist: {code}")

        if start is None:
            start = datetime.today()
        if end is None:
            end = datetime.today()

        balance = Decimal(0.0)
        for entry in self.get_entries(code, start, end):
            balance += entry.balance

        return balance

    def ledger(self, code: str) -> List[LedgerRow]:
        if code not in self.chart.accounts:
            raise KeyError(f"account does not exist: {code}")

        return self.get_ledger_rows(code)

    def get_entries(self, code: str, start: Optional[datetime.date] = None, end: Optional[datetime.date] = None) -> List[Entry]:
        if start is None:
            start = datetime.today()
        elif end is None:
            end = datetime.today()

        entries = []
        for entry in self.get_entries(code, start, end):
            entries.append(entry)
        return entries

    def get_ledger_rows(self, code: str) -> List[LedgerRow]:
        if code not in self.chart.accounts:
            raise KeyError(f"account does not exist: {code}")

        return self.get_ledger_rows(code)

    def walk(self, depth: int) -> List[Tuple[Account, int]]:
        if depth < 0:
            return []
        result = []
        for account in self.chart.accounts:
            if depth == 0:
                result.append((account, 0))
            else:
                current = account.walk(depth - 1)
                result.extend(current)
        return result

# Functions for Statements
def trial_balance(journal: Journal, as_of: Optional[datetime.date] = None) -> str:
    if as_of is None:
        as_of = datetime.today()

    period_start = journal.chart.accounts[0].day
    period_end = journal.chart.accounts[0].day if as_of is not None else datetime.today()

