from typing import Optional, List, Dict, Tuple, Union

@dataclasses.dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, List[str]] = dataclasses.field(default_factory=dict)
    state: Dict[str, Any] = dataclasses.field(default_factory=dict)

@dataclasses.dataclass
class HTTPError(Exception):
    status: int
    reason: str

@dataclasses.dataclass
class BadRequest(HTTPError):
    pass

@dataclasses.dataclass
class Headers:
    pairs: List[Tuple[str, str]] = dataclasses.field(default_factory=lambda: [])

    add(name: str, value: str) -> None:
        """Append a field to the headers."""
        if name not in self.pairs:
            self.pairs.append((name, value))
        else:
            self.pairs[self.pairs.index((name, value))] = (name, value)

    set(name: str, value: str) -> None:
        """Replace a field with the same name, overwriting the first occurrence."""
        if name in self.pairs:
            self.pairs[self.pairs.index(name)] = (name, value)

    get(name: str, default: Optional[str]) -> Optional[str]:
        """Get a header value, or return default if not found."""
        if name not in self.pairs:
            return default
        return self.pairs[self.pairs.index(name)][1]

    get_all(name: str) -> List[Tuple[str, str]]:
        """Return all values in order for a header name."""
        return self.pairs[self.pairs.index(name)]

@dataclasses.dataclass
class Response:
    status: int
    headers: Optional[Headers] = dataclasses.field(default_factory=dict)
    body: bytes

# web/router.py
from typing import Optional, List, Dict, Tuple, Union

@dataclasses.dataclass
class NotFound(HTTPError):
    pass

@dataclasses.dataclass
class MethodNotAllowed(HTTPError):
    allowed: List[str] = dataclasses.field(default_factory=lambda: [])

@dataclasses.dataclass
class Router:
    add: Tuple[str, str, Optional[callable]] = dataclasses.field(default_factory=lambda: ("GET", "/users", None))

    def __init__(self):
        self.handlers = {}

    def add(self, method: str, pattern: str, handler: callable) -> None:
        """Register a handler with the specified method and pattern."""
        if method not in self.handlers:
            self.handlers[method] = handler

    def route(self, pattern: str, methods: Optional[List[str]] = None) -> callable:
        """Return the function unchanged if no method is provided."""
        if methods is None:
            return self.handlers.get(pattern, None)
        return self.handlers.get(pattern, None)

    def dispatch(self, request: Request) -> Response:
        """Resolve the request and return the response."""
        if not self.handlers.get(request.method, []):
            raise MethodNotAllowed()
        handler, params = self.handlers.get(request.method)
        return handler(request, self.dispatch)

# web/middleware.py
from typing import List, Optional, Dict, Tuple, Union, Callable

dataclasses.register_coreclass(Middleware)

@dataclasses.dataclass
class Middleware:
    request: Optional[Request] = None
    call_next: Optional[Callable] = None

    def __call__(self, request: Request, call_next: Callable) -> Response:
        """Handle the middleware chain."""
        response = call_next(request)
        if isinstance(self, Middleware):
            return response
        if isinstance(call_next, Middleware):
            return call_next(response)
        return response

# web/middleware_factories.py
