class TicTacToe:
    board: str
    player: str
    moves: Optional[List[int]] = None

    def __init__(self, board: str = '.........') -> None:
        self.board = board
        self.player = self._get_player()
        self.moves = self._get_moves()

    def _get_player(self) -> str:
        count_X = self.board.count('X')
        count_O = self.board.count('O')
        if count_X == count_O or count_X == count_O + 1:
            return 'X'
        else:
            return 'O'

    def _get_moves(self) -> Optional[List[int]]:
        if len(self.board) != 9 or not all(c in ['X', 'O', '.'] for c in self.board):
            raise ValueError
        if count_X != count_O or count_X != count_O + 1:
            raise ValueError
        return self.board

    def play(self, move: int) -> None:
        if move < 0 or move >= 9 or self._is_valid_move(move):
            raise ValueError
        self.board = self._update_board(move)

    def is_over(self) -> bool:
        for move in self.moves:
            if self._is_valid_move(move):
                return self._is_won()
        return self._is_won()

    def _update_board(self, move: int) -> str:
        if self.board[move] == '.':
            self.board = self._update_board_helper(move)
        return self.board

    def _update_board_helper(self, move: int) -> str:
        self.board[move] = self._get_player()
        return self.board

    def _is_valid_move(self, move: int) -> bool:
        if move < 0 or move >= 9 or not self._is_cell_valid(move):
            return False
        return True

    def _get_player(self) -> str:
        return self.board[move]

    def _is_won(self) -> bool:
        for move in self.moves:
            if self._is_won_from_move(move):
                return True
        return False

    def _is_won_from_move(self, move: int) -> bool:
        return self._is_won_in_line(move)

    def _is_won_in_line(self, move: int) -> bool:
        if move in self.moves:
            return self._is_won_in_line_helper(move)
        return False

    def _is_won_in_line_helper(self, move: int) -> bool:
        if self._is_won_in_column(move) or self._is_won_in_row(move) or self._is_won_in_diagonal(move):
            return True
        return False

    def _is_won_in_column(self, move: int) -> bool:
        return all(self.board[move] == self.board[move + 1] for move in range(8))

    def _is_won_in_row(self, move: int) -> bool:
        return all(self.board[move] == self.board[move + 1] for move in range(8))

    def _is_won_in_diagonal(self, move: int) -> bool:
        return (self.board[0] == self.board[3] == self.board[6] == move) or \
                (self.board[0] == self.board[1] == self.board[2] == move) or \
                (self.board[0] == self.board[1] == self.board[2] == move) or \
                (self.board[0] == self.board[1] == self.board[2] == move) or \
                (self.board[3] == self.board[4] == self.board[5] == move) or \
                (self.board[6] == self.board[7] == self.board[8] == move)
