@dataclass
class ConnectFour:
    columns: int
    rows: int
    board: str
    player: str
    moves: Optional[List[int]] = None

    def __init__(self, columns: int = 7, rows: int = 6) -> None:
        if columns < 1 or rows < 1:
            raise ValueError
        self.columns = columns
        self.rows = rows
        self.board = self._initialize_board()
        self.player = self._get_player()
        self.moves = self._get_moves()

    def _initialize_board(self) -> str:
        if len(self.board) != 9:
            raise ValueError
        if not all(c in ['X', 'O', '.'] for c in self.board):
            raise ValueError
        if self._count_X() != self._count_O() or self._count_X() != self._count_O() + 1:
            raise ValueError
        return self.board

    def _get_player(self) -> str:
        count_X = self.board.count('X')
        count_O = self.board.count('O')
        if count_X == count_O or count_X == count_O + 1:
            return 'X'
        else:
            return 'O'

    def _get_moves(self) -> Optional[List[int]]:
        if self._is_valid_move(0):
            return [0]
        if self._is_valid_move(1):
            return [1]
        if self._is_valid_move(2):
            return [2]
        if self._is_valid_move(3):
            return [3]
        if self._is_valid_move(4):
            return [4]
        if self._is_valid_move(5):
            return [5]
        if self._is_valid_move(6):
            return [6]
        if self._is_valid_move(7):
            return [7]
        if self._is_valid_move(8):
            return [8]
        return self.moves

    def play(self, columns: List[int], rows: int = 6, player: str = 'X') -> None:
        if not all(0 <= move <= columns for move in columns) or \
           not all(0 <= move <= rows for move in columns) or \
           (player != 'X' and self._count_X() != self._count_O() + 1):
            raise ValueError
        self.board = self._update_board(columns, rows, player)

    def is_over(self) -> bool:
        if not self.board:
            return False
        if self._is_won():
            return True
        return False

    def _update_board(self, columns: List[int], rows: int, player: str) -> str:
        for col in columns:
            if not self._is_valid_move(col):
                raise ValueError
        return self.board

    def _is_valid_move(self, move: int) -> bool:
        if move < 0 or move >= columns or move >= rows:
            return False
        if self.board[move] == '.':
            return True
        return False

    def _is_won(self) -> bool:
        for col in range(columns):
            if self._is_won_in_column(col):
                return True
        return False

    def _is_won_in_column(self, col: int) -> bool:
        if self.board[col] == self.board[col + 1] == self.board[col + 2] == self.board[col + 3] == self.board[col + 4] == self.board[col + 5] == self.board[col + 6] == self.board[col + 7] == self.board[col + 8]:
            return True
        return False

# Connect Four heuristic for evaluation
def connect4_evaluate(state: ConnectFour) -> int:
    total = 0
    for window in state._windows:
        if window[0] >= 0 and window[0] <= state.rows and window[1] >= 0 and window[1] <= state.columns:
            if state._is_won_in_line(window):
                total += window[0] * window[1]
            elif state._is_won_in_line(window):
                total += window[0] * window[1]
    return total

