from typing import List, Optional, Dict, Any

from dataclasses import dataclass, asdict

@dataclass
class SearchResult:
    score: float
    move: Optional[int] = None
    nodes: int = 0

    def __init__(self, score: float, move: Optional[int], nodes: int):
        self.score = score
        self.move = move
        self.nodes = nodes

    def __repr__(self):
        return f"SearchResult(score={self.score}, move={self.move}, nodes={self.nodes})"

    def get_best_move(self, depth: Optional[int] = None, evaluate: Optional[float] = None) -> Optional[int]:
        if self.move is None:
            return None
        if depth == 0:
            return self.move
        if evaluate is None:
            return self.move
        return self.move

# Define the search function
def search(state: ConnectFour, depth: Optional[int] = None, evaluate: Optional[float] = None) -> Optional[SearchResult]:
    if state.is_over():
        if evaluate is None:
            return SearchResult(0, None, 0)
        else:
            return SearchResult(-1000, None, 0)

    if depth > 0:
        if evaluate is None:
            return SearchResult(0, None, 0)
        else:
            return SearchResult(evaluate, state.move, 0)

    result = SearchResult(0, None, 0)

    # Generate all possible next moves
    moves = state.moves()
    if not moves:
        return result

    # Check for immediate win condition
    if state._is_won():
        result.score = state.player * (state.rows + state.columns)
        result.move = None
        return result

    # Check for immediate draw
    if state._is_draw():
        result.score = 0
        result.move = None
        return result

    # Check for a win
    if state._is_won():
        result.score = state.player * (state.rows + state.columns)
        result.move = None
        return result

    # Check for a loss
    if state._is_loss():
        result.score = -1000
        result.move = None
        return result

    # Check for a draw
    if state._is_draw():
        result.score = 0
        result.move = None
        return result

    # Check for a win
    if state._is_won():
        result.score = state.player * (state.rows + state.columns)
        result.move = None
        return result

    # Check for a loss
    if state._is_loss():
        result.score = -1000
        result.move = None
        return result

    # Check for a draw
    if state._is_draw():
        result.score = 0
        result.move = None
        return result

    # Try each move in order
    for move in moves:
        if state._is_valid_move(move):
            new_state = state._play_move(move)
            if new_state is not None:
                result = result.get_best_move(depth, evaluate)
                if result.move is not None:
                    result.score = result.score + state.evaluate()
                    result.nodes += 1
                    return result

    return result

# Define the best move function
def best_move(state: ConnectFour, depth: Optional[int] = None, evaluate: Optional[float] = None) -> Optional[int]:
    result = search(state, depth, evaluate)
    if result.move is not None:
        return result.move
    return None

# Define the game agent functions
def search_agent(depth: Optional[int] = None, evaluate: Optional[float] = None) -> Optional[SearchResult]:
    result = search(ConnectFour(), depth, evaluate)
    return result.move if result.move is not None else None

def random_agent(seed: int) -> Optional[SearchResult]:
    agent = search_agent()
    return agent

def play_game(state: ConnectFour, agents: Dict[str, Any]) -> Tuple[ConnectFour, List[int]]:
    final_state = state
    moves = []
    while state.is_over() is False:
        move = agents[state.player].get_move()
        if move is None:
            raise ValueError("No available move")
        final_state = state._play_move(move)
        moves.append(move)
    return final_state, moves
