# resolve is a package-dependency resolver
# it provides a version module, package index, and backtracking solver

from typing import List, Dict, Set, Optional, Tuple, Union

# Version class
class Version:
    def __init__(self, text: str):
        self.text = text

    def __repr__(self):
        return f"{self.text}"

    def __eq__(self, other):
        return self.text == other.text

    def __hash__(self):
        return hash(self.text)

# Range class
class Range:
    def __init__(self, spec: str):
        self.spec = spec

    def __repr__(self):
        return f"{self.spec}"

# PackageIndex class
class PackageIndex:
    def __init__(self):
        self.packages: Dict[str, Dict[str, Range]] = {}

    def add(self, name: str, version: str, requires: Optional[Dict[str, str]] = None):
        if name in self.packages and self.packages[name][version]:
            raise ValueError("cannot add name and version twice")
        if not isinstance(version, str):
            raise ValueError("version must be a string")

        if version in self.packages:
            raise ValueError("cannot add same version twice")

        if requires is not None and version in requires:
            raise ValueError("cannot add version with bad spec")

        self.packages[name] = {
            version: {
                dep: Range(requires.get(dep, ""))
            for dep in requires
        }

    def versions(self, name: str) -> List[Version]:
        if name not in self.packages:
            return []
        return [self.packages[name][version] for version in sorted(self.packages[name].keys(), reverse=True)]

    def requirements(self, name: str, version: str) -> Dict[str, Range]:
        if name not in self.packages:
            return {}
        if version not in self.packages[name]:
            return {}
        return self.packages[name][version]

    def from_dict(self, data: Dict[str, Dict[str, Dict[str, Range]]]):
        for name, required_dict in data.items():
            if name not in self.packages:
                self.packages[name] = {}
            for version, deps in required_dict.items():
                if version not in self.packages[name]:
                    self.packages[name][version] = {}
                for dep, spec in deps.items():
                    if dep not in self.packages[name][version]:
                        self.packages[name][version][dep] = Range(spec)

# Solver class
class resolve:
    def __init__(self, index: PackageIndex, requirements: Dict[str, str]):
        self.index = index
        self.requirements = requirements

    def resolve(self, index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
        order = []
        selected = {}

        def dfs(name: str, reqs: Dict[str, Range]):
            if reqs:
                order.append(name)
                selected[name] = reqs[name]
                return

            if name not in selected:
                if reqs:
                    # Check if this package has a requirement
                    if name in self.requirements:
                        req = self.requirements[name]
                        if req is not None:
                            # Check if the current version is within the requirement
                            current = selected[name]
                            if req is not None and req is not None and current not in req:
                                # This package is already selected with a requirement
                                # Check if the current version is compatible with that requirement
                                req_range = req
                                if req_range is not None:
                                    if req is not None and current not in req_range:
                                        # This package has a requirement that the current version does not satisfy
                                        # So this package cannot be selected
                                        return False
                                elif current not in req:
                                    # This package has no requirement
                                    pass
                                else:
                                    # Check if the current version is within the requirement
                                    if req is not None and current in req:
                                        # This package is already selected with a requirement
                                        # Check if the current version satisfies that requirement
                                        if req is not None and current in req:
                                            # If the current version is compatible, it can be selected
                                            if current in req and current in req:
                                                selected[name] = req
                                                return True
                                            else:
                                                return False
                                    else:
                                        # This package is already selected without a requirement
                                        pass
                            else:
                                # This package has no requirement
                                pass
                        else:
                            # This package has no requirement
                            pass
                else:
                    # This package has no requirement
                    return False
            else:
                return False
        return dfs

# ResolutionError class
class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation

    def __repr__(self):
        return f"ResolutionError for {self.package}: {self.explanation}"

    def __str__(self):
        return self.explanation
