        self.current_dir = self.fs.current_dir

    def run(self, script_path: str) -> tuple:
        try:
            with open(script_path, "r") as f:
                lines = f.readlines()
        except FileNotFoundError:
            raise FSError("error: cannot read script file")

        lines = [line.strip() for line in lines]
        lines = [line.replace('\n', '') for line in lines]
        lines = [line.split() for line in lines]
        commands = [command for command, words in lines if command]

        output = []
        status = 0
        for line_number, command in enumerate(commands):
            if command == "pwd":
                output.append(f"pwd: {self.current_dir}")
                output.append("\n")
                continue
            if command == "cd":
                try:
                    path = self.normalize(command.split()[1])
                    if self.fs is None:
                        self.fs.makedirs(path, parents=True)
                    self.current_dir = Path(self.fs.current_dir).joinpath(path)
                    status = 1
                except FSError as e:
                    output.append(f"{line_number}: cd: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "mkdir":
                try:
                    path = self.normalize(command.split()[1])
                    if self.fs is None:
                        self.fs.makedirs(path, parents=True)
                    self.current_dir = Path(self.fs.current_dir).joinpath(path)
                    status = 1
                except FSError as e:
                    output.append(f"{line_number}: mkdir: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "ls":
                try:
                    path = command.split()[1]
                    if path == '':
                        output.append("[[]]")
                        output.append("\n")
                    else:
                        entries = self.fs.listdir(self.current_dir)
                        entries = [entry for entry in entries if entry.startswith(path)]
                        for entry in entries:
                            output.append(f"{entry}\n")
                except FSError as e:
                    output.append(f"{line_number}: ls: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "rm":
                try:
                    path = command.split()[1]
                    if self.fs is None:
                        self.fs.makedirs(path, parents=True)
                    if self.fs.exists(path):
                        status = 1
                    self.fs.remove(path)
                except FSError as e:
                    output.append(f"{line_number}: rm: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "mv":
                try:
                    src_path = command.split()[1]
                    dst_path = command.split()[2]
                    if self.fs.exists(src_path):
                        if self.fs.exists(dst_path):
                            self.fs.rename(src_path, dst_path)
                            status = 1
                        else:
                            self.fs.mkdir(dst_path, parents=True)
                            status = 1
                    else:
                        if self.fs.exists(dst_path):
                            self.fs.remove(dst_path)
                            status = 1
                        else:
                            status = 1
                except FSError as e:
                    output.append(f"{line_number}: mv: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "write":
                try:
                    path = command.split()[1]
                    if self.fs.exists(path):
                        self.fs.remove(path)
                        status = 1
                    else:
                        status = 1
                except FSError as e:
                    output.append(f"{line_number}: write: {command}: {e.message}")
                    output.append("\n")
                    status = 2
            elif command == "read":
                try:
                    path = command.split()[1]
                    if self.fs.exists(path):
                        status = 1
                    else:
                        status = 2
                except FSError as e:
                    output.append(f"{line_number}: read: {command}: {e.message}")
                    output.append("\n")
            elif command == "find":
                try:
                    path = command.split()[1]
                    if self.fs.exists(path):
