# objstore/objects.py
from collections import namedtuple
from typing import List, Tuple, Optional, Any

def __init__(self):
    """Initialize the objects module."""
    pass

# Objects
class Blob:
    """A blob object with its data."""
    def __init__(self, data: bytes) -> None:
        """Initialize a Blob object."""
        self.data = data

class TreeEntry:
    """A tree entry with its name, kind, and identifier."""
    def __init__(self, name: str, kind: str, oid: str) -> None:
        """Initialize a TreeEntry object."""
        self.name = name
        self.kind = kind
        self.oid = oid

class Tree:
    """A tree object storing a list of TreeEntry objects."""
    def __init__(self, entries: List['TreeEntry']) -> None:
        """Initialize a Tree object."""
        self.entries = entries
        self._sorted_entries = sorted(entries, key=lambda x: x.name.encode('utf-8'))

class Commit:
    """A commit object with its tree, parents, author, timestamp, and message."""
    def __init__(self, tree: str, parents: tuple[str, ...], author: str, timestamp: int, message: str) -> None:
        """Initialize a Commit object."""
        self.tree = tree
        self.parents = parents
        self.author = author
        self.timestamp = timestamp
        self.message = message

# Serialisation
def serialize(obj: Any) -> bytes:
    """Serializes an object into a byte string."""
    if not isinstance(obj, dict):
        return b''

    # Header
    header = b'TYPE LENGTH'
    header += b'\0'  # 1 byte

    # Body
    if isinstance(obj, Blob):
        return header + obj.data
    elif isinstance(obj, Tree):
        # Tree body
        body = b''
        for entry in obj.entries:
            if entry.name == '':  # empty tree
                body += b''
            else:
                # For a blob, we just return the blob's data
                body += entry.name.encode('utf-8') + b'\t' + entry.name.encode('utf-8') + b'\n'
        body += b'\n'  # empty line
        return header + b'.' + str(len(body)) + b'.' + body
    elif isinstance(obj, Commit):
        # Commit body
        body = b''
        tree_entry = obj.tree
        if tree_entry == '':
            body += b''
        else:
            body += tree_entry.encode('utf-8')
        body += b'\n'
        for parent in obj.parents:
            body += parent.encode('utf-8')
        body += b'\n'
        body += obj.author.encode('utf-8')
        body += b' ' + str(obj.timestamp)
        body += b'\n'
        body += obj.message.encode('utf-8')
        return header + b'.' + str(len(body)) + b'.' + body
    return header + b'.' + str(len(obj)) + b'.' + b''

def object_id(obj: Any) -> str:
    """Returns the object identifier (oid) for an object."""
    return obj.oid

def parse_object(raw: bytes) -> Any:
    """Parse a raw object into the object."""
    if not isinstance(raw, bytes):
        raise ValueError("Input is not a byte object.")

    # Header
    header = raw[:len(b'TYPE LENGTH')]

    # Check header
    if header != b'TYPE LENGTH':
        raise ValueError("Invalid header")

    # Body
    body = raw[len(b'TYPE LENGTH')::]

    # Check length
    if len(body) != 0:
        if body[0] != b'\0':
            raise ValueError("Invalid body length")

    # Check type
    if header[0] == b'c':
        # Commit
        if len(body) < b'.':
            raise ValueError("Invalid body length")
        if b'.' not in body:
            raise ValueError("Invalid body")
        if b'.' in body and body[0] != b'\0':
            raise ValueError("Invalid body")
        if b'.' in body and body[0] == b'\0':
            raise ValueError("Invalid body")
        if len(body) < b'.':
            raise ValueError("Invalid body")

    # Check body
    if not isinstance(body, bytes):
        raise ValueError("Input is not a byte object.")

    # Parse the object
    obj = Commit(
        tree=body[4:],
        parents=body[5:],
        author=body[6],
        timestamp=int(body[7]),
        message=body[8:]
    )

    return obj
