from collections import namedtuple
from typing import Optional, List, Dict, Tuple

def __init__(self):
    """Initialize the store module."""
    self._blob = None
    self._tree = None
    self._commit = None
    self._store = {}
    self._prefix = ''

def ObjectStore(self):
    """Initialize the ObjectStore class."""
    self._blob = None
    self._tree = None
    self._commit = None
    self._store = {}
    self._prefix = ''

def put(self, obj: Any) -> str:
    """Store an object with its oid."""
    if not isinstance(obj, dict):
        raise ValueError("Input is not a dictionary object.")

    if obj in self._store:
        return self._store[obj]

    # Check for invalid object
    if not isinstance(obj, dict):
        raise ValueError("Input is not a dictionary object.")

    # Check if it's a blob
    if obj['type'] not in ['blob', 'tree', 'commit']:
        raise ValueError("Invalid object type")

    # Check if it's a tree
    if isinstance(obj, dict):
        if obj['type'] == 'tree':
            if not obj['name']:
                raise ValueError("Empty name")
            if not obj['kind']:
                raise ValueError("Empty kind")
            if not obj['oid']:
                raise ValueError("Empty oid")
            if obj['kind'] != 'tree':
                raise ValueError("Invalid kind")
            if not obj['name'] or not obj['kind'] or not obj['oid']:
                raise ValueError("Invalid object")

    # Check if it's a commit
    if isinstance(obj, dict):
        if obj['type'] == 'commit':
            if not obj['tree']:
                raise ValueError("Tree not set")
            if not obj['parents']:
                raise ValueError("Parents not set")
            if not obj['author']:
                raise ValueError("Author not set")
            if not obj['timestamp']:
                raise ValueError("Timestamp not set")
            if not obj['message']:
                raise ValueError("Message not set")

    # Try to parse the object
    if isinstance(obj, dict):
        if obj['type'] == 'blob':
            if not obj['data']:
                raise ValueError("Data not set")
        elif obj['type'] == 'tree':
            if not obj['name']:
                raise ValueError("Empty name")
            if not obj['kind']:
                raise ValueError("Empty kind")
            if not obj['oid']:
                raise ValueError("Empty oid")
            if not obj['name'] or not obj['kind'] or not obj['oid']:
                raise ValueError("Invalid object")
        elif obj['type'] == 'commit':
            if not obj['tree']:
                raise ValueError("Tree not set")
            if not obj['parents']:
                raise ValueError("Parents not set")
            if not obj['author']:
                raise ValueError("Author not set")
            if not obj['timestamp']:
                raise ValueError("Timestamp not set")
            if not obj['message']:
                raise ValueError("Message not set")

    # Check if it's a tree
    if isinstance(obj, dict):
        if obj['type'] == 'tree':
            if not obj['name']:
                raise ValueError("Empty name")
            if not obj['kind']:
                raise ValueError("Empty kind")
            if not obj['oid']:
                raise ValueError("Empty oid")
            if not obj['name'] or not obj['kind'] or not obj['oid']:
                raise ValueError("Invalid object")

    # Check if it's a commit
    if isinstance(obj, dict):
        if obj['type'] == 'commit':
            if not obj['tree']:
                raise ValueError("Tree not set")
            if not obj['parents']:
                raise ValueError("Parents not set")
            if not obj['author']:
                raise ValueError("Author not set")
            if not obj['timestamp']:
                raise ValueError("Timestamp not set")
            if not obj['message']:
                raise ValueError("Message not set")

    # Store the object
    oid = self._store[obj]
    if oid and oid == obj:
        return oid

    # Store the object
    self._store[obj] = obj
    return obj

def put_raw(self, raw: bytes) -> str:
    """Store a raw object (serialised bytes) into the store."""
    if not isinstance(raw, bytes):
        raise ValueError("Input is not a byte object.")

    # Check if it's a blob
    if raw.startswith(b'TYPE LENGTH'):
        if len(raw) < b'.':
            raise ValueError("Invalid body length")
        if b'.' in raw:
            if raw[0] != b'\0':
                raise ValueError("Invalid body")

    # Parse the object
    if isinstance(raw, bytes):
        obj = self.parse_object(raw)
        return obj

def get(self, oid: str) -> Any:
    """Get an object by its oid."""
    if oid not in self._store:
        return None

    return self._store[oid]

def get_raw(self, oid: str) -> bytes:
    """Get the raw serialisation of an object by its oid."""
    if oid not in self._store:
        raise ObjectNotFound("Object not found")

    return self._store[oid]

def oid_in_store(self, oid: str) -> Optional[str]:
    """Check if an object is stored."""
    return self._store.get(oid, None)

def write_tree(self, files: Dict[str, bytes]) -> str:
    """Write a tree structure into the store."""
    if not isinstance(files, dict):
        raise ValueError("Input is not a dictionary object.")

    # Create a directory if needed
    if not files:
        return ''

    tree_oid = self._commit_oid()
    tree_entries = []

    for path, file in files.items():
        # Create the file entry
        if file:
            if not path.startswith('.') or not path.endswith('.'):
                raise ValueError("Invalid path format")

            # Handle empty files
            if not path or not path.endswith('.'):
                if path == '':  # empty file
                    tree_entries.append(TreeEntry('', 'blob', tree_oid))
                else:
                    tree_entries.append(TreeEntry(path, 'blob', tree_oid))
            else:
                tree_entries.append(TreeEntry(path, 'tree', tree_oid))

            if file:
                tree_entries.append(TreeEntry(path, 'tree', tree_oid))

        # Create the directory entry
        if path in self._store:
            tree_entries.append(TreeEntry(path, 'tree', tree_oid))
        else:
            tree_entries.append(TreeEntry(path, 'tree', tree_oid))

    # Sort entries by name
    tree_entries.sort(key=lambda x: x.name.encode('utf-8'))

    # Create the root tree
    tree = Tree(entries=tree_entries)

    # Store the tree
    self._tree = tree
    return tree_oid

def read_tree(self, oid: str) -> Dict[str, bytes]:
    """Read the tree structure from the store."""
    if not isinstance(oid, str) or oid not in self._store:
        raise ObjectNotFound("Tree not found")

    tree = self._store[oid]
    return tree.entries

def commit(self, tree: str, parents=(), *args, **kwargs) -> Optional[str]:
    """Commit a change with the provided parameters."""
    if not isinstance(tree, str):
        raise ValueError("Tree must be a string")

    if not isinstance(parents, tuple):
        raise ValueError("Parents must be a tuple")

    if not isinstance(args, tuple):
        raise ValueError("Arguments must be a tuple")

    if not isinstance(kwargs, dict):
        raise ValueError("Keyword arguments must be a dictionary")

    # Check if the tree is valid
    if not tree or not self._tree:
        raise ObjectNotFound("Tree not found")

    # Check if the parents are valid
    if not parents or not isinstance(parents, tuple):
        raise ValueError("Parents must be a tuple")

    # Check if the tree is a tree
    if not isinstance(tree, str):
        raise ValueError("Tree must be a string")

    # Check if the parents are valid
    if not parents or not isinstance(parents, tuple):
        raise ValueError("Parents must be a tuple")

    # Check if the tree is a tree
    if not isinstance(tree, str):
        raise ValueError("Tree must be a string")

    # Check if the parents are valid
    if not parents or not isinstance(parents, tuple):
        raise ValueError("Parents must be a tuple")

    # Check if the tree is a tree
    if not isinstance(tree, str):
        raise ValueError("Tree must be a string")

    # Check if the parents are valid
    if not parents or not isinstance(parents, tuple):
        raise ValueError("Parents must be a tuple")

    # Check if the tree is a tree
    if not isinstance(tree, str):
        raise ValueError("Tree must be a string")

    # Store the commit
    commit = Commit(tree=tree, parents=parents, **kwargs)
    commit_oid = self._commit_oid()

    # Update the store
    self._store[commit_oid] = commit

    return commit_oid

def log(self, oid: str, first_parent=False) -> List[str]:
    """Get the list of commits for a given object, ordered by timestamp."""
    if not isinstance(oid, str) or oid not in self._store:
        raise ObjectNotFound("Object not found")

    commit = self._store[oid]
    commits = []

    # Commit and ancestors
    if first_parent:
        commits.append(commit)
        while commit and commit.parents:
            commit = commit.parents[0]
    else:
        commits.append(commit)

    while commit and commit.parents:
        commit = commit.parents[0]

    # Collect all commits
    while commit:
        commits.append(commit)
        commit = commit.parents[0]

    return commits
