from collections import namedtuple
from typing import List, Dict, Optional, Tuple

def __init__(self):
    """Initialize the diff module."""
    pass

class Change:
    """A change with status, path, old, and new (blob oids, None on the side where the file does not exist)."""
    def __init__(self, status: str, path: str, old: Optional[str], new: Optional[str]) -> None:
        """Initialize a change."""
        self.status = status
        self.path = path
        self.old = old
        self.new = new

def diff_trees(store: Dict[str, Any], old: Dict[str, Any], new: Dict[str, Any]) -> List[Change]:
    """Compare two trees and return changes per file path."""
    if not isinstance(store, dict) or not isinstance(old, dict) or not isinstance(new, dict):
        raise ValueError("Input must be a dictionary")

    # Create a mapping from path to tree entry
    tree_map = {}
    for path, entry in store.items():
        tree_map[path] = entry

    # Create a mapping from path to tree entry
    new_tree_map = {}
    for path, entry in new.items():
        new_tree_map[path] = entry

    # Create a mapping from path to tree entry
    old_tree_map = {}
    for path, entry in old.items():
        old_tree_map[path] = entry

    # Create a mapping from path to tree entry
    diff_changes = []
    for path in old_tree_map:
        # Compare tree entries
        if old_tree_map[path] and new_tree_map.get(path, None):
            # If both exist, check for changes
            if old_tree_map[path].kind != new_tree_map.get(path, None).kind:
                diff_changes.append(Change('M', path, old_tree_map[path].oid, new_tree_map.get(path, None).oid))
        elif old_tree_map.get(path, None) and new_tree_map.get(path, None):
            # If both exist, check for changes
            if old_tree_map.get(path, None).kind == new_tree_map.get(path, None).kind:
                diff_changes.append(Change('M', path, old_tree_map.get(path, None).oid, new_tree_map.get(path, None).oid))
        elif old_tree_map.get(path, None) and not new_tree_map.get(path, None):
            # If only one exists, create a file
            diff_changes.append(Change('A', path, old_tree_map.get(path, None).oid, None))
        elif not old_tree_map.get(path, None) and new_tree_map.get(path, None):
            # If only one exists, create a file
            diff_changes.append(Change('D', path, None, new_tree_map.get(path, None).oid))

    return diff_changes

def diff_commits(store: Dict[str, Any], old: Dict[str, Any], new: Dict[str, Any]) -> List[Change]:
    """Diffs the trees of two commits and returns changes per file."""
    if not isinstance(store, dict) or not isinstance(old, dict) or not isinstance(new, dict):
        raise ValueError("Input must be a dictionary")

    # Create a mapping from path to tree entry
    tree_map = {}
    for path, entry in store.items():
        tree_map[path] = entry

    # Create a mapping from path to tree entry
    new_tree_map = {}
    for path, entry in new.items():
        new_tree_map[path] = entry

    # Create a mapping from path to tree entry
    old_tree_map = {}
    for path, entry in old.items():
        old_tree_map[path] = entry

    # Create a mapping from path to tree entry
    diff_changes = []

    # Add all entries from new tree
    for path in new_tree_map:
        if path in old_tree_map:
            # Compare tree entries
            if old_tree_map[path].kind != new_tree_map.get(path, None).kind:
                diff_changes.append(Change('M', path, old_tree_map.get(path, None).oid, new_tree_map.get(path, None).oid))
        elif old_tree_map.get(path, None):
            # Create a file entry
            diff_changes.append(Change('A', path, old_tree_map.get(path, None).oid, None))
        elif not old_tree_map.get(path, None):
            # Create a file entry
            diff_changes.append(Change('D', path, None, new_tree_map.get(path, None).oid))

    return diff_changes

def format_changes(changes: List[Change]) -> str:
    """Format the changes into one line per change."""
    if not changes:
        return ''

    return '\n'.join(f"{change.status}\t{change.path}\n" for change in changes)
