from typing import Dict, List, Optional, NamedTuple, Tuple, cast

from dataclasses import dataclass, field
from decimal import Decimal, getcontext
from collections import defaultdict

class ValueError(Exception):
    pass

class Equal(NamedTuple):
    members: Optional[List[str]] = None

class Exact(NamedTuple):
    shares: Dict[str, int]

class Percent(NamedTuple):
    shares: Dict[str, Decimal]

class Expense(NamedTuple):
    description: str
    paid_by: str
    amount: str
    split: Tuple[Equal, Exact, Percent]

class Group(NamedTuple):
    members: List[str]

class Transfer(NamedTuple):
    payer: str
    payee: str
    amount: int

class Balances(NamedTuple):
    balances: Dict[str, int]
    total: int

def parse_amount(text: str) -> int:
    """Parse an amount in cents, optional with decimal format."""
    parts = text.split('.')
    if len(parts) == 1:
        return int(text)
    cents = int(parts[0])
    if '.' in text:
        cents = cents * 100 + int(parts[1])
    return cents

def format_amount(cents: int) -> str:
    """Format an amount with two decimal places."""
    return f"{cents:.2f}"

def load_group(data: Dict[str, Any]) -> Group:
    """Load a group from a dictionary."""
    members = data.get("members")
    if not members:
        return Group()

    expenses = data.get("expenses")
    payments = data.get("payments")

    if not expenses:
        return Group(members)

    return Group(members, expenses, payments)

def format_balances(bals: Balances) -> str:
    """Format the balances for printing."""
    if not bals:
        return "All settled.\n"

    result = []
    for name, balance in bals.balances.items():
        if balance > 0:
            result.append(f"{name}: {balance}\n")
        else:
            result.append(f"{name}: -{balance}\n")

    return "\n".join(result)

def settle(bals: Balances) -> List[Transfer]:
    """Settle the balances by transferring money as per rules."""
    if not bals:
        return []

    transfers = []
    for member, balance in bals.balances.items():
        if balance > 0:
            transfers.append(Transfer(payer=member, payee="", amount=balance))
        elif balance < 0:
            transfers.append(Transfer(payer="", payee=member, amount=balance))

    # Greedy rule: always take the creditor with most positive balance and the debtor with most negative
    # (ties broken alphabetically)
    while any(bal > 0 for _, bal in bals.balances.items()):
        creditor = max(bals.balances.keys(), key=lambda name: (bals.balances[name] > 0, name))
        debtor = min(bals.balances.keys(), key=lambda name: (bals.balances[name] < 0, name))
        if (bals.balances[creditor] > bals.balances[debtor]) or \
           (bals.balances[creditor] == bals.balances[debtor] and creditor < debtor):
            amount = bals.balances[creditor]
            transfers.append(Transfer(payer=creditor, payee=debtor, amount=amount))
            bals.balances[creditor] -= amount
            bals.balances[debtor] += amount

    return transfers

def format_plan(transfers: List[Transfer]) -> str:
    """Format the settlement plan."""
    if not transfers:
        return "All settled.\n"

    result = []
    for transfer in transfers:
        result.append(f"{transfer.payer} pays {transfer.payee} {format_amount(transfer.amount)}\n")

    return "\n".join(result)
